pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Best-Fit Decreasing logic combined with lookahead-based fragmentation prevention.
    // We aim to minimize the post_residual (Best Fit) while penalizing fragmentation
    // that makes future items (including lookahead) difficult to place.

    let mut score = post_residual as f64;

    // 1. Penalty for leaving very small, unusable gaps (1..9)
    // Small gaps are "dead space" because min item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Integration: If the next item cannot fit in this post_residual,
    // we penalize it slightly to encourage keeping bins open that could accommodate the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 3. Global State: If we are near the end of the stream, prioritize filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // 4. New Bin Logic: If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only open a new bin if the current fit is extremely poor (post_residual is very high).
    if bin_residual == bin_capacity {
        // High penalty to open new bins unless no other options exist or current options are terrible.
        score = 60.0; 

        // If we have few open bins, opening a new one is cheaper.
        score -= (open_bins_count as f64) * 0.5;
    } else {
        // Favor bins that align with the mean density of existing bins
        if (post_residual as f64) > mean_residual {
            score += 5.0;
        }
    }

    // 5. Critical Constraint: If this is the only bin that fits the item, reward it heavily
    // to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (fragmentation) that cannot fit common item sizes
    // We penalize residual space between 1 and 9 as these are hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if next_item_size is large, favor bins that leave enough room for it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize placing current item if it blocks the next one from fitting here
            score += 25.0;
        } else {
            // Reward placing current item if it leaves perfect room for the next item
            if (post_residual - next_item_size) < 5 {
                score -= 15.0;
            }
        }
    }

    // New Bin Logic: Only open a new bin if we are forced to, or if all open bins are poor fits
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin
        score = 85.0;
        // Reduce cost if we have many open bins already, to prevent massive fragmentation
        if open_bins_count > 5 {
            score -= (open_bins_count as f64) * 2.0;
        }
    } else {
        // Prefer bins that are "tighter" fits for the current item
        // This is a variation of Best-Fit, but adjusted by the mean_residual
        score += (post_residual as f64 - mean_residual).abs() * 0.5;
    }

    // Reward utilizing bins that are already "half-full" to keep packing density high
    let current_fill = (bin_capacity - bin_residual) as f64;
    score -= current_fill * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize large post_residuals (wasted space)
    // We want post_residual to be as close to 0 as possible.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Penalty: 
    // Small residuals that are too small to fit common items (e.g., < 10) are "dead space".
    // If post_residual is small but > 0, it's often worse than having it be 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead logic:
    // If next_item_size is large, favor bins that can still accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.5;
        } else {
            // Penalty if we block the next item from fitting
            score += 15.0;
        }
    }

    // 4. Thresholding against New Bin opening:
    // If this is an empty bin (new bin candidate), only pick it if current fits are very poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many bins already or if fitting_bins_count is 0.
        // We set a base cost for opening a new bin to discourage it unless necessary.
        score = 45.0 + (open_bins_count as f64 * 0.1);
    } else {
        // If it's a tight fit, heavily reward it.
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // 5. Mean-based balancing:
    // Avoid creating bins that deviate significantly from the current average density.
    let density_diff = (post_residual as f64 - mean_residual).abs();
    score += density_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Favor small residuals that are multiples of common item sizes (e.g., 20, 25)
    // to keep the residual useful for future items.
    let harmonic_mod = (post_residual % 20) as f64;
    score += harmonic_mod * 0.5;

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Fragmentation Avoidance: Penalize residuals that are too small to fit the smallest expected items (10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. New Bin Logic: If this is an empty bin, evaluate based on stream progression.
    // Discourage opening new bins early in the process unless the fit is very poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score = 35.0 + (progress * 15.0);
    }

    // 5. Density Balancing: Penalize bins that deviate significantly from the mean residual.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 6. Scarcity Reward: If only one bin can fit this item, prioritize it to save open bin slots.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize smaller post_residual (Best Fit)
    // We apply a non-linear penalty for small residuals that are "useless" (e.g., < 10)
    // to avoid fragmenting space, but only if we are not at the end of the stream.
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        10.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Coupling: If we have many open bins, we prefer to fill them tightly.
    // If we have few, we are more tolerant of a larger post_residual to keep space open.
    let bin_density_factor = (open_bins_count as f64) / (1.0 + mean_residual);

    // Lookahead: If the next item is large, we strongly penalize bins that would 
    // leave a post_residual too small to accommodate it.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * (1.5 - progress)
    } else {
        0.0
    };

    // New bin logic:
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    // We want to make it expensive to open a new bin unless existing options are poor.
    let base_score = if bin_residual == bin_capacity {
        // Higher cost for new bins, diminishing as we reach the end of the stream
        // to ensure we don't leave items stranded.
        40.0 + (20.0 * (1.0 - progress))
    } else {
        post + dead_space_penalty + lookahead_penalty + (bin_density_factor * post * 0.5)
    };

    // Adjust for scarcity: if this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        base_score - 50.0
    } else {
        base_score
    }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    // We want to minimize remaining space, but penalize "near-empty" bins that are hard to fill later.
    let mut score = post_res;

    // Penalty for creating a bin that is too small for the next item (Lookahead anticipation).
    // If next_item_size is large and post_res is smaller than it, we penalize this placement.
    if next_item_size > 0 && post_res < next_item_size as f64 {
        score += (next_item_size as f64 - post_res) * 1.5;
    }

    // Dynamic thresholding: as the stream progresses, we become more conservative about 
    // opening new bins. If this is a new bin (bin_residual == bin_capacity), 
    // heavily penalize it unless the existing fitting bins are extremely poor fits.
    if bin_residual == bin_capacity {
        // Penalty scales with progress to discourage opening new bins late in the stream.
        // We only open a new bin if the existing bins leave too much unusable space.
        score += 15.0 + (progress * 40.0);
    } else {
        // Reward bins that have a smaller residual than the global mean, 
        // to encourage packing items into already "tight" bins.
        if post_res < mean_residual {
            score -= (mean_residual - post_res) * 0.5;
        }
    }

    // If this is the only bin that can fit the item, reward it to prevent 
    // premature new bin creation unless absolutely necessary.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Non-linear coupling: penalize very small residuals (dead space) 
    // that are unlikely to be filled by future items (e.g., < 10).
    if post_res > 0.0 && post_res < 10.0 {
        score += (10.0 - post_res) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Base penalty for opening a new bin is the capacity, scaled by current density
        // We only open a new bin if the best fit in existing bins is extremely poor
        score = 85.0 + (progress * 15.0);
    } else {
        // Penalty for creating 'dead space' that is too small for average future items
        // Smaller post_residual is usually good (Best Fit), but we penalize if 
        // the remaining space becomes useless (< 10) while other bins are available.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // Lookahead: if the next item is large, favor bins that can accommodate it
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0;
        }

        // Dynamic thresholding: If we are late in the stream, be more aggressive about
        // filling existing bins to reduce the total count.
        if fitting_bins_count == 1 {
            score -= 10.0; // Reward finishing a bin if it's the only option
        }

        // Penalty for increasing the number of active bins relative to the mean residual
        // This discourages fragmentation of space across too many bins.
        score += (open_bins_count as f64) * 2.0;
        score -= mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large gaps left behind (Best-Fit principle)
    // We favor post_residual being as close to 0 as possible.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: Reward placements where post_residual fits the next_item_size perfectly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // High reward for "perfect" future fit (within 5 units)
            let gap = (post_residual - next_item_size) as f64;
            score -= (100.0 - gap) * 2.5;
        } else {
            // Penalty if this placement prevents the next item from fitting here
            score += 20.0;
        }
    }

    // 3. New Bin Thresholding: Discourage opening new bins unless necessary.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very low (bins are full)
        // or if we have very few options.
        if mean_residual > 15.0 && fitting_bins_count > 0 {
            score += 150.0;
        } else {
            score += 40.0;
        }
    }

    // 4. Density Balancing: Favor placing items in bins that are closer to the global mean residual
    // to maintain a uniform distribution of fill levels.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. Last Chance Logic: If this is the only bin that fits, prioritize it heavily
    // to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    score
}
